      music = "103_LZY",
      renwu = "npc",
      sentence = "It wasn't hard to find him—he was either posing calmly with an award certificate in hand, or standing proudly with a trophy in the next... These were facets of him I had never seen before, glimpses into a boyhood brimming with excellence and composure.",
